1	using Microsoft.EntityFrameworkCore;
2	using seed_a_backend.Api.Data;
3	using seed_a_backend.Api.DTOs;
4	
5	namespace seed_a_backend.Api.Services;
6	
7	public class VeranstaltungenService(AppDbContext db) : IVeranstaltungenService
8	{
9	    public async Task<IReadOnlyList<VeranstaltungListeDto>> GetVeranstaltungenAsync(DateOnly? von = null, DateOnly? bis = null, string? spielstaetteId = null)
10	    {
11	        var query = db.Veranstaltungen
12	            .Include(v => v.Raum)
13	            .ThenInclude(r => r!.Spielstaette)
14	            .AsQueryable();
15	
16	        if (von is not null)
17	        {
18	            var tagesbeginn = EuropaBerlinZeitzone.Tagesbeginn(von.Value);
19	            query = query.Where(v => v.Zeitpunkt >= tagesbeginn);
20	        }
21	
22	        if (bis is not null)
23	        {
24	            var tagesende = EuropaBerlinZeitzone.Tagesende(bis.Value);
25	            query = query.Where(v => v.Zeitpunkt <= tagesende);
26	        }
27	
28	        if (!string.IsNullOrWhiteSpace(spielstaetteId))
29	        {
30	            query = query.Where(v => v.Raum!.SpielstaetteId == spielstaetteId);
31	        }
32	
33	        return await query
34	            .OrderBy(v => v.Zeitpunkt)
35	            .Select(v => new VeranstaltungListeDto(
36	                v.Id,
37	                v.Titel,
38	                v.Raum!.SpielstaetteId,
39	                v.Raum!.Spielstaette!.Name,
40	                v.Zeitpunkt))
41	            .ToListAsync();
42	    }
43	
44	    public async Task<VeranstaltungDetailDto?> GetVeranstaltungAsync(string id)
45	    {
46	        return await db.Veranstaltungen
47	            .Include(v => v.Raum)
48	            .ThenInclude(r => r!.Spielstaette)
49	            .Where(v => v.Id == id)
50	            .Select(v => new VeranstaltungDetailDto(
51	                v.Id,
52	                v.Titel,
53	                v.Beschreibung,
54	                v.DauerMinuten,
55	                v.Altersfreigabe,
56	                v.Raum!.Spielstaette!.Name,
57	                v.Raum!.Name,
58	                v.Zeitpunkt,
59	                v.Preiskategorien.OrderBy(p => p.Id).Select(p => new PreiskategorieDto(p.Id, p.Name, p.Preis)).ToList()))
60	            .FirstOrDefaultAsync();
61	    }
62	
63	    public async Task<SitzplanDto?> GetSitzplanAsync(string veranstaltungId)
64	    {
65	        var veranstaltung = await db.Veranstaltungen
66	            .Include(v => v.Raum)
67	            .FirstOrDefaultAsync(v => v.Id == veranstaltungId);
68	
69	        if (veranstaltung is null)
70	        {
71	            return null;
72	        }
73	
74	        var raum = veranstaltung.Raum!;
75	
76	        var belegteCodes = (await db.Sitzplatzbelegungen
77	            .Where(s => s.VeranstaltungId == veranstaltungId)
78	            .Select(s => s.SitzplatzCode)
79	            .ToListAsync())
80	            .ToHashSet();
81	
