15	    {
16	        var connectionString = SqlServerTestDatabase.BuildConnectionString(nameof(VeranstaltungenEndpointTests));
17	
18	        // Datenbank leer + migriert vorbereiten, damit Program.cs beim Hoststart den Anfangsdatenbestand seedet
19	        var db = await SqlServerTestDatabase.CreateFreshContextAsync(nameof(VeranstaltungenEndpointTests));
20	        await db.DisposeAsync();
21	
22	        _factory = new WebApplicationFactory<Program>().WithWebHostBuilder(builder =>
23	        {
24	            builder.UseSetting("ConnectionStrings:Default", connectionString);
25	        });
26	        _client = _factory.CreateClient();
27	    }
28	
29	    public async ValueTask DisposeAsync()
30	    {
31	        _client.Dispose();
32	        await _factory.DisposeAsync();
33	        await SqlServerTestDatabase.DropAsync(nameof(VeranstaltungenEndpointTests));
34	    }
35	
36	    [Fact]
37	    public async Task GetVeranstaltungen_LiefertAlleVeranstaltungenAufsteigendNachZeitpunktSortiert()
38	    {
39	        var veranstaltungen = await _client.GetFromJsonAsync<List<VeranstaltungListeDto>>("/veranstaltungen");
40	
41	        Assert.NotNull(veranstaltungen);
