  - [ ] `seed-a-backend.Api/Services/BuchungenService.cs` (neue Datei) — Kernstück der Story:
    ```csharp
    using Microsoft.EntityFrameworkCore;
    using seed_a_backend.Api.Data;
    using seed_a_backend.Api.DTOs;
    using seed_a_backend.Api.Models;

    namespace seed_a_backend.Api.Services;

    public class BuchungenService(AppDbContext db, IReferenzGenerator referenzGenerator) : IBuchungenService
    {
        private const int MaxReferenzVersuche = 5;

        public async Task<BuchungErgebnis> BuchungAnlegenAsync(string veranstaltungId, BuchungAnlegenRequestDto request)
        {
            var veranstaltung = await db.Veranstaltungen
                .Include(v => v.Preiskategorien)
                .FirstOrDefaultAsync(v => v.Id == veranstaltungId);

            if (veranstaltung is null)
            {
                return BuchungErgebnis.VeranstaltungFehlt();
            }

            foreach (var position in request.Positionen)
            {
                if (veranstaltung.Preiskategorien.All(p => p.Id != position.PreiskategorieId))
                {
                    return BuchungErgebnis.PreiskategorieFehlt(position.PreiskategorieId);
                }
            }

            var angefragteCodes = request.Positionen.Select(p => p.SitzplatzCode).ToList();

            for (var versuch = 1; versuch <= MaxReferenzVersuche; versuch++)
            {
                var buchung = new Buchung
                {
                    Id = Guid.NewGuid().ToString(),
                    Referenz = referenzGenerator.Naechste(),
                    VeranstaltungId = veranstaltungId,
                    Name = request.Name,
                    Email = request.Email,
                    Status = BuchungStatus.Aktiv,
                    Gesamtpreis = 0m,
                };

                var positionen = new List<Buchungsposition>();
                var gesamtpreis = 0m;
                foreach (var position in request.Positionen)
                {
                    var kategorie = veranstaltung.Preiskategorien.First(p => p.Id == position.PreiskategorieId);
                    gesamtpreis += kategorie.Preis;
                    positionen.Add(new Buchungsposition
                    {
                        BuchungId = buchung.Id,
                        SitzplatzCode = position.SitzplatzCode,
                        PreiskategorieId = kategorie.Id,
                        PreisSnapshot = kategorie.Preis,
                    });
                }

                buchung.Gesamtpreis = gesamtpreis;

                var belegungen = request.Positionen.Select(position => new Sitzplatzbelegung
                {
                    VeranstaltungId = veranstaltungId,
                    SitzplatzCode = position.SitzplatzCode,
                    BuchungId = buchung.Id,
                }).ToList();

                await using var transaction = await db.Database.BeginTransactionAsync();
                db.Buchungen.Add(buchung);
                db.Buchungspositionen.AddRange(positionen);
                db.Sitzplatzbelegungen.AddRange(belegungen);

                try
                {
                    await db.SaveChangesAsync();
                    await transaction.CommitAsync();

                    return BuchungErgebnis.Erfolg(new BuchungDto(
                        buchung.Referenz,
                        buchung.VeranstaltungId,
                        buchung.Name,
                        buchung.Email,
                        buchung.Status.ToString(),
                        buchung.Gesamtpreis,
                        positionen.Select(p => new BuchungspositionDto(
                            p.SitzplatzCode,
                            p.PreiskategorieId,
                            veranstaltung.Preiskategorien.First(k => k.Id == p.PreiskategorieId).Name,
                            p.PreisSnapshot)).ToList()));
                }
                catch (DbUpdateException)
                {
                    await transaction.RollbackAsync();
                    db.ChangeTracker.Clear();

                    var tatsaechlichBelegt = await db.Sitzplatzbelegungen
                        .Where(s => s.VeranstaltungId == veranstaltungId && angefragteCodes.Contains(s.SitzplatzCode))
                        .Select(s => s.SitzplatzCode)
                        .ToListAsync();

                    if (tatsaechlichBelegt.Count > 0)
                    {
                        return BuchungErgebnis.Konflikt(tatsaechlichBelegt);
                    }

                    // Keiner der angefragten Plaetze ist tatsaechlich belegt: der Fehlschlag kam nicht von
                    // Sitzplatzbelegung, sondern von der UNIQUE-Constraint auf Buchung.Referenz. Naechster
                    // Versuch mit neuer Referenz (bis MaxReferenzVersuche erreicht ist).
                }
            }

            return BuchungErgebnis.ReferenzFehlgeschlagen();
        }
    }
    ```
  - [ ] **Disaster Prevention — `db.ChangeTracker.Clear()` nach Rollback ist zwingend:** Ohne diesen Aufruf blieben `buchung`/`positionen`/`belegungen` aus dem gescheiterten Versuch im Change Tracker als `Added` markiert. Der nachfolgende `Sitzplatzbelegungen`-Read in derselben Methode würde dann fälschlich auch die (nie committeten) eigenen Entitäten des gescheiterten Versuchs zurückliefern, und ein zweiter Schleifendurchlauf würde versuchen, dieselben (jetzt doppelt getrackten) Entitäten erneut einzufügen — ein zweiter, verwirrender Fehler statt des korrekten Konflikt-/Retry-Verhaltens.
  - [ ] **Warum kein `try/catch` um die Preiskategorie-Prüfung, aber um `SaveChangesAsync`:** Die Preiskategorie-Prüfung (AC #4) ist eine reine In-Memory-Prüfung gegen bereits geladene Daten (`veranstaltung.Preiskategorien`), kein DB-Schreibzugriff — sie muss **vor** dem ersten Transaktionsversuch passieren, nicht als Teil der Retry-Schleife, da eine ungültige Preiskategorie sich durch Wiederholen nicht "repariert".
  - [ ] **Warum die Unterscheidung Konflikt vs. Referenz-Kollision ohne Exception-Message-Parsing funktioniert (AD-4-Konformität):** Beide Fälle lösen dieselbe `DbUpdateException` bei `SaveChangesAsync` aus (verschiedene `UNIQUE`-Constraints). Statt die SQL-Fehlermeldung zu parsen, liest der Code nach dem Rollback erneut, ob einer der **angefragten** Sitzplätze tatsächlich als `Sitzplatzbelegung`-Zeile existiert. Da die Referenz vollständig unabhängig von den Sitzplatz-Codes ist, kann eine reine Referenz-Kollision niemals dazu führen, dass einer der angefragten Sitzplätze plötzlich als belegt erscheint — der Read liefert in diesem Fall zuverlässig eine leere Liste, und die Schleife interpretiert das korrekt als "nächster Referenz-Versuch nötig".

